(function(root){
 const visible=el=>!!el&&!!el.getClientRects().length;
 const text=el=>(el.innerText||el.textContent||'').replace(/\s+/g,' ').trim();
 const buttons=doc=>Array.from(doc.querySelectorAll('button')).filter(b=>visible(b)&&!b.disabled&&b.getAttribute('aria-disabled')!=='true');
 function unique(list,label){if(list.length!==1)throw Error(label+' is missing or ambiguous.');return list[0]}
 function hero(doc,name){return unique(buttons(doc).filter(b=>Array.from(b.querySelectorAll('img')).some(img=>img.alt===name)&&! /^(BAN|PICK)(?:\s|$)/i.test(text(b))),'Hero '+name)}
 function confirm(doc,name,action){return unique(buttons(doc).filter(b=>(action==='ban'?/^BAN(?:\s|$)/i:/^PICK(?:\s|$)/i).test(text(b))&&(Array.from(b.querySelectorAll('img')).some(img=>img.alt===name)||text(b).toLowerCase()=== (action+' '+name).toLowerCase())),'Confirm '+action+' '+name)}
 function setSelect(el,value){if(!Array.from(el.options).some(o=>o.value===value&&!o.disabled))throw Error('Role option missing or taken.');Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype,'value').set.call(el,value);el.dispatchEvent(new Event('change',{bubbles:true}))}
 function roleControl(doc,id,name){const selects=Array.from(doc.querySelectorAll('select[id="lineup-role-'+id+'"]')).filter(el=>visible(el)&&!el.disabled);if(selects.length)return unique(selects,'Role control '+name);const focus=unique(buttons(doc).filter(b=>(b.getAttribute('aria-label')||'').startsWith(name+', ')),'Role card '+name);focus.click();return null}
 function strategy(doc,question,value){const option=value==='a'?question.optionA:question.optionB;return unique(buttons(doc).filter(b=>{const spans=Array.from(b.querySelectorAll('span'));return spans.some(s=>text(s)===option.name)&&spans.some(s=>text(s)===value.toUpperCase())}),'Strategy '+question.title)}
 function strategyComplete(doc){const headings=Array.from(doc.querySelectorAll('h2')).filter(el=>visible(el)&&text(el)==='Strategy calls');return headings.length===1&&/\bDone\b/i.test(text(headings[0].parentElement.parentElement))}
 function strategyProgress(doc,total){const headings=Array.from(doc.querySelectorAll('h2')).filter(el=>visible(el)&&text(el)==='Strategy calls');if(headings.length!==1)return null;const header=text(headings[0].parentElement.parentElement);if(/\bDone\b/i.test(header))return total;const call=header.match(/\bCall\s+(\d+)\s*\/\s*(\d+)\b/i);return call&&Number(call[2])===total&&Number(call[1])>=1&&Number(call[1])<=total?Number(call[1])-1:null}
 function itemSlots(doc,id,name){const select=Array.from(doc.querySelectorAll('select[id="lineup-role-'+id+'"]')).find(visible);if(!select){roleControl(doc,id,name);return null}return buttons(select.parentElement).filter(b=>/^Slot \d/.test(b.title||'')||b.querySelector('img')&&b.title)}
 function setItem(doc,id,name,slot,item){if(!item)throw Error('Recommended item missing.');const dialog=Array.from(doc.querySelectorAll('[role="dialog"]')).find(el=>visible(el)&&(el.getAttribute('aria-label')||'')==='Choose item for slot '+(slot+1));if(dialog){unique(buttons(dialog).filter(b=>Array.from(b.querySelectorAll('img')).some(img=>img.alt===item.name)),'Item '+item.name).click();return 'picked'}const slots=itemSlots(doc,id,name);if(!slots)return 'focused';if(slots.length!==6)throw Error('Six item slots could not be verified for '+name);if(Array.from(slots[slot].querySelectorAll('img')).some(img=>img.alt===item.name))return 'verified';slots[slot].click();return 'opened'}
 function prepSeconds(doc){for(const el of doc.querySelectorAll('[aria-label="Match drafts with prep countdown"],[aria-label^="Strategy prep,"]')){if(!visible(el))continue;const clock=((el.getAttribute('aria-label')||'')+' '+text(el)).match(/\b(\d{1,2}):(\d{2})\b/);if(clock)return Number(clock[1])*60+Number(clock[2])}return null}
 function prepStatus(doc){const content=Array.from(doc.body.children).filter(el=>el.id!=='dcl-advisor'&&visible(el)).map(text).join(' ');if(/\bLive match\b/i.test(content))return 'started';if(content.includes('They are finishing strategy')&&content.includes('Waiting for opponent'))return 'locked';if(/Starting match|Locking/.test(content))return 'pending';if(content.includes('Draft complete')&&content.includes('Opening strategy'))return 'opening';return null}
 function proceed(doc){return unique(buttons(doc).filter(b=>text(b)==='Continue'),'Continue')}
 root.AdvisorGame={visible,text,buttons,hero,confirm,setSelect,roleControl,strategy,strategyComplete,strategyProgress,itemSlots,setItem,prepSeconds,prepStatus,proceed};
})(typeof window==='undefined'?globalThis:window);
